from collections import Counter

def transform(g):
    h, w = len(g), len(g[0])
    cnt = Counter(x for r in g for x in r)
    bg = cnt.most_common(1)[0][0]
    marker = cnt.most_common(2)[1][0]
    pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == marker]
    r0, r1 = min(p[0] for p in pts), max(p[0] for p in pts)
    c0, c1 = min(p[1] for p in pts), max(p[1] for p in pts)
    out = [row[:] for row in g]
    # fill background cells on the perimeter of the markers' bounding box
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg and (r in (r0, r1) and c0 <= c <= c1 or c in (c0, c1) and r0 <= r <= r1):
                out[r][c] = 2
    def runs(idxs):
        rs = []; s = idxs[0]; p = idxs[0]
        for x in idxs[1:]:
            if x == p + 1:
                p = x
            else:
                rs.append((s, p)); s = p = x
        rs.append((s, p)); return rs
    # fill gaps between runs of >=2 consecutive markers along a row or column
    for r in range(h):
        idx = [c for c in range(w) if g[r][c] == marker]
        if len(idx) >= 2:
            rs = runs(idx)
            for (a1, a2), (b1, b2) in zip(rs, rs[1:]):
                if a2 - a1 + 1 >= 2 and b2 - b1 + 1 >= 2:
                    for c in range(a2 + 1, b1):
                        if g[r][c] == bg:
                            out[r][c] = 2
    for c in range(w):
        idx = [r for r in range(h) if g[r][c] == marker]
        if len(idx) >= 2:
            rs = runs(idx)
            for (a1, a2), (b1, b2) in zip(rs, rs[1:]):
                if a2 - a1 + 1 >= 2 and b2 - b1 + 1 >= 2:
                    for r in range(a2 + 1, b1):
                        if g[r][c] == bg:
                            out[r][c] = 2
    return out


